import{_ as a,c as t,o as r,ag as o}from"./chunks/framework.DuVOYUUM.js";const p=JSON.parse('{"title":"Sensors","description":"","frontmatter":{"order":3},"headers":[],"relativePath":"projects/igvc-2024/software/sensors.md","filePath":"projects/igvc-2024/software/sensors.md","lastUpdated":1790647345000}'),s={name:"projects/igvc-2024/software/sensors.md"};function i(n,e,l,h,c,d){return r(),t("div",null,e[0]||(e[0]=[o('<h1 id="sensors" tabindex="-1">Sensors <a class="header-anchor" href="#sensors" aria-label="Permalink to &quot;Sensors&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#zed-2i-depth-camera">ZED 2i Depth Camera</a></li><li><a href="#gps">GPS</a></li><li><a href="#imu">IMU</a></li></ul></nav><h2 id="zed-2i-depth-camera" tabindex="-1">ZED 2i Depth Camera <a class="header-anchor" href="#zed-2i-depth-camera" aria-label="Permalink to &quot;ZED 2i Depth Camera&quot;">​</a></h2><p>Horizon utilizes a ZED2i stereo camera for vision purposes. The ZED2i is a depth camera that was designed for outdoor use with built-in sensors for metrics such as acceleration, temperature, and air pressure. These alongside the main depth camera functionality and the included <a href="https://www.stereolabs.com/developers/release" target="_blank" rel="noreferrer">ZED SDK</a> make the ZED2i an invaluable piece of hardware in our software subsystem. Further <a href="https://www.stereolabs.com/docs/get-started-with-zed" target="_blank" rel="noreferrer">documentation</a> can be found on the stereolabs website.</p><h2 id="gps" tabindex="-1">GPS <a class="header-anchor" href="#gps" aria-label="Permalink to &quot;GPS&quot;">​</a></h2><p>Horizon must get within one (1) meter of GPS waypoints found along the course. To achieve this, a ZED-F9P module is utilized. Using the SparkFun GPS-RTK-SMA Kit. This GPS is capable of three-dimensional accuracy down to 10mm. Documentation on all parts of this kit including schematics, data sheets, and a GitHub repository can be found on the <a href="https://www.sparkfun.com/products/18292" target="_blank" rel="noreferrer">SparkFun Website</a>. Along with that, there is an extensive Arduino library for reading and controlling the GPS can be found <a href="https://github.com/sparkfun/SparkFun_u-blox_GNSS_v3" target="_blank" rel="noreferrer">on GitHub</a>.</p><h2 id="imu" tabindex="-1">IMU <a class="header-anchor" href="#imu" aria-label="Permalink to &quot;IMU&quot;">​</a></h2><p>In addition to the BNO055 IMU provided by electrical, Horizon also makes use of the IMU built into the ZED which helps with position tracking for it, as well as localization overall. Since the BNO055 IMU is powered by electrical, the acceleration/velocity data sent out by the IMU is sent out over CAN. These two IMUs are fused to get a better reading of the robot&#39;s pose overall.</p>',8)]))}const f=a(s,[["render",i]]);export{p as __pageData,f as default};
